def pt(v):return [round(pcbnew.ToMM(v.x),6),round(pcbnew.ToMM(v.y),6)]
def vec(p):return pcbnew.VECTOR2I(pcbnew.FromMM(p[0]),pcbnew.FromMM(p[1]))
def apply(board):
 items={t.m_Uuid.AsString():t for t in board.GetTracks()}
 for old in PLAN['delete']:
  if old['uuid'] not in items:raise ValueError('missing deletion '+old['uuid'])
  t=items[old['uuid']]
  if t.GetNetname()!=old['net'] or pt(t.GetStart())!=old['start'] or pt(t.GetEnd())!=old['end']:raise ValueError('changed deletion source '+old['uuid'])
 for c in PLAN['changes']:
  if c['uuid'] not in items:raise ValueError('missing change '+c['uuid'])
  t=items[c['uuid']]
  current=t.GetPosition() if c.get('via') else t.GetStart() if c['endpoint']=='start' else t.GetEnd()
  if pt(current)!=c['old']:raise ValueError('changed endpoint '+c['uuid'])
 for a in PLAN['add']:
  n=board.FindNet(a['net'])
  if n is None or n.GetNetCode()<=0:raise ValueError('missing net '+a['net'])
 for c in PLAN['changes']:
  t=items[c['uuid']]
  if c.get('via'):t.SetPosition(vec(c['new']))
  elif c['endpoint']=='start':t.SetStart(vec(c['new']))
  else:t.SetEnd(vec(c['new']))
 for old in PLAN['delete']:board.RemoveNative(items[old['uuid']])
 added=[]
 for a in PLAN['add']:
  for start,end in zip(a['points'],a['points'][1:]):
   t=pcbnew.PCB_TRACK(board);t.SetNet(board.FindNet(a['net']));t.SetLayer(board.GetLayerID(a['layer']));t.SetWidth(pcbnew.FromMM(a['width']));t.SetStart(vec(start));t.SetEnd(vec(end));t.SetLocked(True);board.Add(t);added.append(t)
 for spec in PLAN.get('vias',[]):
  v=pcbnew.PCB_VIA(board);v.SetNet(board.FindNet(spec['net']));v.SetPosition(vec(spec['xy']));v.SetViaType(pcbnew.VIATYPE_THROUGH);v.SetLayerPair(pcbnew.F_Cu,pcbnew.B_Cu);v.SetWidth(pcbnew.FromMM(spec['diameter']));v.SetDrill(pcbnew.FromMM(spec['drill']));v.SetLocked(True);board.Add(v);added.append(v)
 return dict(deleted=len(PLAN['delete']),changes=len(PLAN['changes']),added=len(added))
